head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _1 : rowIndex 를 인덱스(Number) 로 호출하는 버전. (rowIndex 는 Number 만이므로 ID 분리 없음 → 단일 샘플)
//     mergeCells="byrow"(가로병합) 그리드에서 특정 Row 를 자동 병합 대상에서 추가/삭제(mergeRow)하여 검증.
scwin.tData = {
    "description" : "[gridView > M > mergeRow]<br/>Body Row 인덱스를 사용하여 특정 Row 를 자동 병합 대상에서 추가하거나 삭제합니다.",
    "validation" : [
        "mergeCells, mergeCellsFixedCols, mergeCellsFixedRows 속성값이 'never' 가 아닌 경우 해당 영역에 적용됩니다.",
        "rowIndex(필수) 파라미터로 자동 병합 대상에서 추가/삭제하려는 Body Row 인덱스를 설정합니다. Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "include(선택, 기본 true) 파라미터를 true 로 설정 시 해당 Row 를 자동 병합 대상에 추가합니다.",
        "include(선택) 파라미터를 false 로 설정 시 해당 Row 를 자동 병합 대상에서 삭제합니다. 모든 Row 는 자동 병합 대상에 추가되어 있으므로 false 를 설정하여 삭제해야 합니다.",
        "include 파라미터를 생략하면 기본값 true 로 동작하여 해당 Row 를 자동 병합 대상에 추가합니다.",
        "mergeRow() 메소드 실행만으로는 화면이 갱신되지 않으며, mergeCells() 등 병합 실행 메소드를 별도로 실행해야 병합이 반영됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 가로(byrow) 병합이 드러나도록 같은 Row 내 인접 컬럼 동일값으로 구성.
//  행 | col1 | col2 | col3 | col4
//  ---+------+------+------+------
//   0 |  A   |  A   |  A   |  1     → col1~col3 가로병합
//   1 |  B   |  B   |  C   |  C     → col1~col2, col3~col4 가로병합
//   2 |  D   |  E   |  F   |  F     → col3~col4 가로병합
//   3 |  G   |  G   |  G   |  G     → col1~col4 가로병합
//  · 모든 Row 가 자동 병합 대상이면 위와 같이 각 행이 가로병합됨.
//  · 특정 Row 를 mergeRow(rowIndex, false) 로 대상에서 빼면 그 Row 만 가로병합되지 않음.
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "A", "col3": "A", "col4": "1" },
    { "col1": "B", "col2": "B", "col3": "C", "col4": "C" },
    { "col1": "D", "col2": "E", "col3": "F", "col4": "F" },
    { "col1": "G", "col2": "G", "col3": "G", "col4": "G" }
];



// comp 생성 : mergeCells="byrow" 그리드 1개를 동적 생성.
//  ★ 초기에는 모든 Body Row 가 자동 병합 대상.
//     (mergeRow() 메소드로 특정 Row 인덱스를 추가/삭제하여 검증)
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="mergeCells=byrow(가로병합). Row 인덱스는 0부터(행0~행3). 초기엔 전체 Row 가 자동 병합 대상. 데이터는 각 행 인접 컬럼 동일값으로 가로병합 표시"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // mergeCells="byrow" (같은 Row 내 동일값 연속 Cell 을 colSpan(가로) 병합)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id,
        mergeCells: "byrow",
        defaultCellHeight: 34
    });

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:380px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeRow sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// rowIndex 파라미터 수집 (인덱스 Number)
scwin.getRowIndexParam = function () {
    return Number(par_rowIndex.getValue());
};



// include 파라미터 수집 (par_include 는 gdl_boolean 바인딩)
//  ★ value 는 인덱스('1'/'2'/'3') 이고 의미는 label('','true','false') 이므로 getText() 로 판정.
//     ('' → 생략, 'true' → true, 'false' → false)  (getValue() 오용 시 판정 오류 발생)
//  반환 : { omit:true } (생략) 또는 { omit:false, value:Boolean }
scwin.getIncludeParam = function () {
    let t = par_include.getText();
    if (t === '' || t === undefined || t === null) return { omit: true };
    return { omit: false, value: (t === 'true') };
};



// mergeRow + 병합실행 : mergeRow(rowIndex[, include]) 호출 후 mergeCells("byrow") 로 반영
//  · include 미설정('') 이면 rowIndex 만 전달(생략 호출) → 기본값 true 동작
//  · include true/false 이면 명시 전달
scwin.btn_mergeRowRun_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let rowIndex = scwin.getRowIndexParam();
    let inc = scwin.getIncludeParam();

    if (inc.omit) {
        // include(선택) 생략 → 기본값 true
        target1.mergeRow(rowIndex);
        bottom.setReturnValue("호출 : target1.mergeRow(" + rowIndex + ")  // include 생략 → 기본값 true");
    } else {
        target1.mergeRow(rowIndex, inc.value);
        bottom.setReturnValue("호출 : target1.mergeRow(" + rowIndex + ", " + inc.value + ")");
    }

    // 병합 실행 메소드(mergeCells) 를 별도 실행해야 화면에 반영됨
    target1.mergeCells("byrow");
    bottom.setReturnValue("병합 실행 : target1.mergeCells('byrow')");

    scwin.printMergeState(bottom);
}



// mergeRow 만 호출 : mergeCells 를 다시 실행하지 않고 mergeRow() 만 호출.
//  @spec — mergeRow() 메소드 실행만으로는 화면이 갱신되지 않음을 보이기 위해
//          호출 전/후 가로병합된 Row 상태를 비교 출력한다. (변화 없음 → 이어서 위 버튼으로 병합 실행 필요)
scwin.btn_mergeRowOnly_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let rowIndex = scwin.getRowIndexParam();
    let inc = scwin.getIncludeParam();

    let beforeRows = scwin.collectMergedRows();

    if (inc.omit) {
        target1.mergeRow(rowIndex);
        bottom.setReturnValue("호출 : target1.mergeRow(" + rowIndex + ")  // include 생략 → 기본값 true (mergeCells 미실행)");
    } else {
        target1.mergeRow(rowIndex, inc.value);
        bottom.setReturnValue("호출 : target1.mergeRow(" + rowIndex + ", " + inc.value + ")  // mergeCells 미실행");
    }

    let afterRows = scwin.collectMergedRows();
    bottom.setReturnValue("화면 가로병합된 Body Row (호출 전) : " + (beforeRows.length ? beforeRows.join(",") : "없음"));
    bottom.setReturnValue("화면 가로병합된 Body Row (호출 후) : " + (afterRows.length ? afterRows.join(",") : "없음"));
    bottom.setReturnValue("화면 갱신 여부 : " + (beforeRows.join(",") !== afterRows.join(",")) + "  // false=미갱신(mergeCells 등 병합 실행 메소드 별도 실행 필요)");
}



// 현재 화면에 가로(colSpan) 병합된 Body Row 목록을 수집 (앵커 td 의 colSpan 기준)
scwin.collectMergedRows = function () {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    let mergedRowSet = {};
    let seen = {};
    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수(display:none/offsetParent null) td 제외
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;
        let cs = td.colSpan || 1;
        if (cs > 1) {
            mergedRowSet["행" + r] = true;
        }
    }
    return Object.keys(mergedRowSet).sort();
}



// 병합 상태 확인 : 각 Body td 의 colSpan 을 읽어 가로(➡) 병합 그룹과
//  가로병합된 Body Row 목록을 출력. (td 셀렉터는 gid = target1.id 사용 — e.target.id 는 버튼 id 라 사용 불가)
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let colSpanCnt = 0;
    let descs = [];
    let mergedRowSet = {};
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수되어 화면에 표시되지 않는 td 제외
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (cs > 1) {
            colSpanCnt++;
            mergedRowSet["행" + r] = true;
            let val = (td.textContent || "").trim();
            descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
        }
    }

    bottom.setReturnValue("판정 : " + (colSpanCnt > 0 ? "가로(colSpan) 병합" : "병합 없음") + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }

    let mergedRows = Object.keys(mergedRowSet).sort();
    bottom.setReturnValue("가로병합된 Body Row (화면 표시 기준) : " + (mergedRows.length ? mergedRows.join(",") : "없음"));

    // mergeRow 대상 상태 : 전체 Body Row 별 자동 병합 대상 여부.
    //  · target1.mergeRowObj[index] === false → 대상에서 삭제됨(X), 그 외(undefined/true) → 대상 O(기본)
    let rowCnt = scwin.MERGE_DATA.length;
    let mro = target1.mergeRowObj || {};
    let targetDescs = [];
    for (let ri = 0; ri < rowCnt; ri++) {
        let isTarget = (mro[ri] !== false);
        targetDescs.push("행" + ri + ":" + (isTarget ? "O" : "X"));
    }
    bottom.setReturnValue("[mergeRow 대상] " + targetDescs.join(" / ") + "  // O=병합대상 / X=대상에서 삭제(include false)");
}
